"""Standard-library HTTP server for the incident-operations interface."""

from __future__ import annotations

import json
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path
from urllib.parse import parse_qs, urlsplit

from .escalation import EscalationWorker
from .models import (
    EscalationClaimError,
    Incident,
    IncidentNotFoundError,
    IncidentStatus,
    InvalidTransitionError,
    Severity,
    VersionConflictError,
    audit_event_to_dict,
    incident_to_dict,
)
from .sqlite_store import SQLiteIncidentStore

STATIC_DIR = Path(__file__).with_name("static")


def _json_default(value: object) -> object:
    if hasattr(value, "value"):
        return value.value
    raise TypeError(f"cannot encode {type(value).__name__}")


def _summary_counts(store: SQLiteIncidentStore) -> dict:
    incidents = store.list()
    by_status: dict[str, int] = {status.value: 0 for status in IncidentStatus}
    by_severity: dict[str, int] = {sev.value: 0 for sev in Severity}
    for incident in incidents:
        by_status[incident.status.value] += 1
        by_severity[incident.severity.value] += 1
    return {
        "total": len(incidents),
        "by_status": by_status,
        "by_severity": by_severity,
    }


def create_server(
    store: SQLiteIncidentStore,
    host: str = "127.0.0.1",
    port: int = 8080,
) -> ThreadingHTTPServer:
    """Construct and bind a server without starting its request loop."""

    class Handler(BaseHTTPRequestHandler):
        def do_GET(self) -> None:
            parts = urlsplit(self.path)
            path = parts.path
            if path == "/api/incidents":
                self._list_incidents(parts)
                return
            if path.startswith("/api/incidents/"):
                self._incident_detail(path[len("/api/incidents/"):])
                return
            if path == "/api/summary":
                self._json(200, _summary_counts(store))
                return
            if path in {"/", "/index.html"}:
                self._file("index.html", "text/html; charset=utf-8")
                return
            if path == "/app.js":
                self._file("app.js", "text/javascript; charset=utf-8")
                return
            if path == "/styles.css":
                self._file("styles.css", "text/css; charset=utf-8")
                return
            self.send_error(404)

        def do_POST(self) -> None:
            parts = urlsplit(self.path)
            path = parts.path
            if path == "/api/alerts":
                self._ingest_alert()
                return
            if path == "/api/escalations/run":
                worker_id = parse_qs(parts.query).get("worker_id", ["http"])[0]
                worker = EscalationWorker(store, worker_id)
                completed = worker.run_until_idle()
                self._json(
                    200,
                    [incident_to_dict(item) for item in completed],
                )
                return
            self.send_error(404)

        def do_PATCH(self) -> None:
            parts = urlsplit(self.path)
            path = parts.path
            if not path.startswith("/api/incidents/"):
                self.send_error(404)
                return
            incident_id = path[len("/api/incidents/"):]
            if not incident_id:
                self.send_error(404)
                return
            try:
                payload = self._body()
            except (json.JSONDecodeError, ValueError) as exc:
                self._json(400, {"error": f"invalid JSON: {exc}"})
                return
            if not isinstance(payload, dict):
                self._json(400, {"error": "request body must be a JSON object"})
                return
            if "expected_version" not in payload:
                self._json(
                    400, {"error": "expected_version is required"}
                )
                return
            try:
                incident = store.update(
                    incident_id,
                    int(payload["expected_version"]),
                    owner=payload.get("owner"),
                    status=payload.get("status"),
                    idempotency_key=payload.get("idempotency_key"),
                )
            except IncidentNotFoundError as exc:
                self._json(404, {"error": str(exc)})
                return
            except VersionConflictError as exc:
                self._json(409, {"error": str(exc)})
                return
            except (InvalidTransitionError, ValueError, TypeError) as exc:
                self._json(400, {"error": str(exc)})
                return
            self._json(200, incident_to_dict(incident))

        # ------------------------------------------------------------------
        # Route helpers
        # ------------------------------------------------------------------

        def _list_incidents(self, parts) -> None:
            query = parse_qs(parts.query)
            status = query.get("status", [None])[0]
            severity = query.get("severity", [None])[0]
            owner = query.get("owner", [None])[0]
            try:
                incidents = store.list(status=status, severity=severity, owner=owner)
            except (ValueError, TypeError) as exc:
                self._json(400, {"error": str(exc)})
                return
            self._json(200, [incident_to_dict(item) for item in incidents])

        def _incident_detail(self, incident_id: str) -> None:
            incident = store.get(incident_id)
            if incident is None:
                self._json(404, {"error": f"unknown incident {incident_id}"})
                return
            payload = incident_to_dict(incident)
            payload["events"] = [
                audit_event_to_dict(event) for event in store.events(incident_id)
            ]
            self._json(200, payload)

        def _ingest_alert(self) -> None:
            try:
                payload = self._body()
            except (json.JSONDecodeError, ValueError) as exc:
                self._json(400, {"error": f"invalid JSON: {exc}"})
                return
            if not isinstance(payload, dict):
                self._json(400, {"error": "request body must be a JSON object"})
                return
            try:
                incident, created = store.ingest_alert(
                    fingerprint=payload["fingerprint"],
                    title=payload["title"],
                    severity=payload["severity"],
                    source=payload.get("source", "unknown"),
                    details=payload.get("details"),
                    idempotency_key=payload.get("idempotency_key"),
                )
            except (KeyError, ValueError, TypeError) as exc:
                self._json(400, {"error": str(exc)})
                return
            self._json(201 if created else 200, incident_to_dict(incident))

        # ------------------------------------------------------------------
        # Plumbing
        # ------------------------------------------------------------------

        def _body(self) -> dict:
            length = int(self.headers.get("Content-Length", "0"))
            raw = self.rfile.read(length)
            if not raw:
                return {}
            return json.loads(raw)

        def _file(self, name: str, content_type: str) -> None:
            body = (STATIC_DIR / name).read_bytes()
            self.send_response(200)
            self.send_header("Content-Type", content_type)
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)

        def _json(self, status: int, value: object) -> None:
            body = json.dumps(value, default=_json_default).encode("utf-8")
            self.send_response(status)
            self.send_header("Content-Type", "application/json")
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)

        def log_message(self, format: str, *args: object) -> None:
            return

    return ThreadingHTTPServer((host, port), Handler)

