)
from .sqlite_store import SQLiteIncidentStore
from .web import create_server


def parser() -> argparse.ArgumentParser:
    result = argparse.ArgumentParser(
        prog="python -m incident_ops.cli",
        description="Durable incident operations center.",
    )
    result.add_argument("--db", required=True, help="SQLite database path")
    subcommands = result.add_subparsers(dest="command", required=True)

    serve = subcommands.add_parser("serve", help="Run the HTTP server")
    serve.add_argument("--host", default="127.0.0.1")
    serve.add_argument("--port", type=int, default=8080)

    ingest = subcommands.add_parser("ingest", help="Ingest an alert as JSON")
    ingest.add_argument("alert", help="JSON alert object")

    list_parser = subcommands.add_parser("list", help="List incidents")
    list_parser.add_argument("--status")
    list_parser.add_argument("--severity")
    list_parser.add_argument("--owner")

    update = subcommands.add_parser("update", help="Update an incident")
    update.add_argument("incident_id")
    update.add_argument("update", help="JSON update object")

    escalate = subcommands.add_parser("escalate", help="Run the escalation worker")
    escalate.add_argument("--worker-id", default="cli-worker")
    escalate.add_argument("--max-incidents", type=int, default=None)

    subcommands.add_parser("export", help="Write NDJSON dump to stdout")
    subcommands.add_parser("import", help="Read NDJSON dump from stdin")
    return result


def _emit(value: object) -> None:
    sys.stdout.write(json.dumps(value) + "\n")


def _store(args: argparse.Namespace) -> SQLiteIncidentStore:
    return SQLiteIncidentStore(args.db)


def main(argv: list[str] | None = None) -> int:
    args = parser().parse_args(argv)
    try:
        if args.command == "serve":
            return _serve(args)
        if args.command == "ingest":
            return _ingest(args)
        if args.command == "list":
            return _list(args)
        if args.command == "update":
            return _update(args)
        if args.command == "escalate":
            return _escalate(args)
        if args.command == "export":
            return _export(args)
        if args.command == "import":
            return _import(args)
    except (ValueError, KeyError, json.JSONDecodeError, TypeError) as exc:
        _emit({"error": str(exc)})
        return 2
    except (
        IncidentNotFoundError,
        InvalidTransitionError,
        VersionConflictError,
    ) as exc:
        _emit({"error": str(exc)})
        return 1
    return 0


def _serve(args: argparse.Namespace) -> int:
    server = create_server(_store(args), args.host, args.port)
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        pass
    finally:
        server.server_close()
    return 0


def _ingest(args: argparse.Namespace) -> int:
    payload = json.loads(args.alert)
    if not isinstance(payload, dict):
        raise ValueError("alert must be a JSON object")
    incident, created = _store(args).ingest_alert(
        fingerprint=payload["fingerprint"],
        title=payload["title"],
        severity=payload["severity"],
        source=payload.get("source", "unknown"),
        details=payload.get("details"),
        idempotency_key=payload.get("idempotency_key"),
    )
    _emit({"created": created, "incident": incident_to_dict(incident)})
    return 0


def _list(args: argparse.Namespace) -> int:
    incidents = _store(args).list(
        status=args.status, severity=args.severity, owner=args.owner
    )
    for incident in incidents:
        _emit(incident_to_dict(incident))
    return 0


def _update(args: argparse.Namespace) -> int:
    payload = json.loads(args.update)
    if not isinstance(payload, dict):
        raise ValueError("update must be a JSON object")
    if "expected_version" not in payload:
        raise ValueError("expected_version is required")
    incident = _store(args).update(
        args.incident_id,
        int(payload["expected_version"]),
        owner=payload.get("owner"),
        status=payload.get("status"),
        idempotency_key=payload.get("idempotency_key"),
    )
    _emit(incident_to_dict(incident))
    return 0


def _escalate(args: argparse.Namespace) -> int:
    worker = EscalationWorker(_store(args), args.worker_id)
    for incident in worker.run_until_idle(max_incidents=args.max_incidents):
        _emit(incident_to_dict(incident))
    return 0


def _export(args: argparse.Namespace) -> int:
    incidents, events = _store(args).export_rows()
    for incident in incidents:
        _emit({"type": "incident", "incident": incident_to_dict(incident)})
    for event in events:
        _emit({"type": "audit", "event": audit_event_to_dict(event)})
    return 0


def _import(args: argparse.Namespace) -> int:
    store = _store(args)
    incidents: list[Incident] = []
    events: list[AuditEvent] = []
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        record = json.loads(line)
        if not isinstance(record, dict):
            raise ValueError("each line must be a JSON object")
        kind = record.get("type")
        if kind == "incident":
            incidents.append(incident_from_dict(record["incident"]))
        elif kind == "audit":
            events.append(audit_event_from_dict(record["event"]))
        else:
            raise ValueError(f"unknown export record type: {kind!r}")
    inserted = store.import_rows(incidents, events)
    _emit({"imported": inserted})
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

