  feedback: document.querySelector("#feedback"),
  summaryTotal: document.querySelector("#summary-total"),
  summaryStatus: document.querySelector("#summary-status"),
  summarySeverity: document.querySelector("#summary-severity"),
  statusFilter: document.querySelector("#status-filter"),
  severityFilter: document.querySelector("#severity-filter"),
  ownerInput: document.querySelector("#owner-input"),
  dialog: document.querySelector("#alert-dialog"),
  alertForm: document.querySelector("#alert-form"),
  newAlert: document.querySelector("#new-alert-action"),
  alertCancel: document.querySelector("#alert-cancel"),
};

function setFeedback(message, kind = "info") {
  state.feedback = message;
  els.feedback.textContent = message;
  els.feedback.className = "feedback " + kind;
}

async function fetchJson(url, options) {
  const response = await fetch(url, options);
  let body = null;
  try {
    body = await response.json();
  } catch (err) {
    body = null;
  }
  return { ok: response.ok, status: response.status, body };
}

function buildQuery() {
  const params = new URLSearchParams();
  const { status, severity, owner } = state.filters;
  if (status) params.set("status", status);
  if (severity) params.set("severity", severity);
  if (owner) params.set("owner", owner);
  const q = params.toString();
  return q ? "?" + q : "";
}

async function refresh() {
  const [listResult, summaryResult] = await Promise.all([
    fetchJson("/api/incidents" + buildQuery()),
    fetchJson("/api/summary"),
  ]);

  if (!listResult.ok) {
    setFeedback("Could not load incidents", "error");
    return;
  }
  state.incidents = listResult.body || [];
  renderList();

  if (summaryResult.ok && summaryResult.body) {
    state.summary = summaryResult.body;
    renderSummary(summaryResult.body);
  }

  if (state.selectedIncidentId) {
    const id = state.selectedIncidentId;
    const detail = await fetchJson("/api/incidents/" + encodeURIComponent(id));
    if (detail.ok) {
      renderDetail(detail.body);
    } else if (detail.status === 404) {
      state.selectedIncidentId = null;
      renderDetail(null);
    }
  }
}

function renderSummary(summary) {
  els.summaryTotal.textContent = String(summary.total);
  const statuses = ["open", "acknowledged", "resolved"];
  els.summaryStatus.replaceChildren(
    ...statuses.map((s) => {
      const chip = document.createElement("span");
      chip.className = "summary-chip status-" + s;
      chip.textContent = `${s} ${summary.by_status[s] ?? 0}`;
      return chip;
    })
  );
  const severities = ["P1", "P2", "P3", "P4"];
  els.summarySeverity.replaceChildren(
    ...severities.map((s) => {
      const chip = document.createElement("span");
      chip.className = "summary-chip severity-" + s;
      chip.textContent = `${s} ${summary.by_severity[s] ?? 0}`;
      return chip;
    })
  );
}

function severityClass(severity) {
  return "severity-" + (severity || "");
}

function renderList() {
  if (!state.incidents.length) {
    const empty = document.createElement("p");
    empty.className = "empty";
    empty.textContent = "No incidents match the current filters.";
    els.list.replaceChildren(empty);
    return;
  }
  els.list.replaceChildren(...state.incidents.map(renderRow));
}

function renderRow(incident) {
  const row = document.createElement("button");
  row.type = "button";
  row.className = "incident-row" + (incident.id === state.selectedIncidentId ? " selected" : "");
  row.setAttribute("data-testid", "incident-row");
  row.setAttribute("data-id", incident.id);

  const badge = document.createElement("span");
  badge.className = "sev " + severityClass(incident.severity);
  badge.textContent = incident.severity;

  const body = document.createElement("span");
  body.className = "row-body";
  const title = document.createElement("span");
  title.className = "row-title";
  title.textContent = incident.title;
  const meta = document.createElement("span");
  meta.className = "row-meta";
  meta.textContent = `${incident.status} · alerts ${incident.alert_count} · v${incident.version}${incident.owner ? " · " + incident.owner : ""}`;
  body.append(title, meta);

  row.append(badge, body);
  row.addEventListener("click", () => selectIncident(incident.id));
  return row;
}

async function selectIncident(id) {
  state.selectedIncidentId = id;
  const rows = els.list.querySelectorAll(".incident-row");
  rows.forEach((row) => row.classList.toggle("selected", row.getAttribute("data-id") === id));
  const result = await fetchJson("/api/incidents/" + encodeURIComponent(id));
  if (result.ok) {
    renderDetail(result.body);
  } else {
    renderDetail(null);
    setFeedback("Could not load incident " + id, "error");
  }
