    ["Alerts", incident.alert_count],
    ["Version", incident.version],
    ["Escalation", incident.escalation_level],
    ["Created", formatTime(incident.created_at)],
    ["Updated", formatTime(incident.updated_at)],
    ["SLA deadline", formatTime(incident.sla_deadline)],
  ];
  for (const [label, value] of factList) {
    const fact = document.createElement("span");
    fact.className = "fact";
    fact.innerHTML = `<span class="fact-label">${label}</span><span class="fact-value"></span>`;
    fact.querySelector(".fact-value").textContent = String(value);
    facts.append(fact);
  }

