  ackBtn.type = "button";
  ackBtn.textContent = "Acknowledge";
  ackBtn.setAttribute("data-testid", "acknowledge-action");
  ackBtn.disabled = incident.status !== "open";
  ackBtn.addEventListener("click", () => applyUpdate(incident, { status: "acknowledged" }));

  const resolveBtn = document.createElement("button");
  resolveBtn.type = "button";
  resolveBtn.textContent = "Resolve";
  resolveBtn.setAttribute("data-testid", "resolve-action");
  resolveBtn.disabled = incident.status === "resolved";
  resolveBtn.addEventListener("click", () => applyUpdate(incident, { status: "resolved" }));

  controls.append(ownerLabel, ackBtn, resolveBtn);

