  timeline.className = "timeline";
  timeline.setAttribute("data-testid", "timeline");
  const timelineTitle = document.createElement("h3");
  timelineTitle.textContent = "Audit timeline";
  timeline.append(timelineTitle);

  const events = incident.events || [];
  if (!events.length) {
    const empty = document.createElement("p");
    empty.className = "empty";
    empty.textContent = "No events recorded.";
    timeline.append(empty);
  } else {
    const ol = document.createElement("ol");
    for (const event of events) {
      const li = document.createElement("li");
      li.className = "event event-" + event.type;
      const time = document.createElement("span");
      time.className = "event-time";
      time.textContent = formatTime(event.timestamp);
      const label = document.createElement("span");
      label.className = "event-type";
      label.textContent = event.type;
      const detail = document.createElement("span");
      detail.className = "event-details";
      detail.textContent = JSON.stringify(event.details);
      li.append(time, label, detail);
      ol.append(li);
    }
    timeline.append(ol);
  }

  els.detail.append(head, facts, controls, timeline);
}

async function applyUpdate(incident, patch) {
  const result = await fetchJson("/api/incidents/" + encodeURIComponent(incident.id), {
    method: "PATCH",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ expected_version: incident.version, ...patch }),
  });
  if (result.ok) {
    setFeedback("Incident updated", "ok");
  } else if (result.status === 409) {
    setFeedback("Conflict: someone else changed this incident. Refreshing.", "error");
  } else {
    setFeedback((result.body && result.body.error) || "Update failed", "error");
  }
  await refresh();
}

function formatTime(value) {
  if (value === null || value === undefined || value === 0) return "—";
  const date = new Date(value * 1000);
  return date.toLocaleString();
}

function bindFilters() {
  els.statusFilter.addEventListener("change", (e) => {
    state.filters.status = e.target.value;
    refresh();
  });
  els.severityFilter.addEventListener("change", (e) => {
    state.filters.severity = e.target.value;
    refresh();
  });
  let ownerTimer = null;
  els.ownerInput.addEventListener("input", (e) => {
    state.filters.owner = e.target.value.trim();
    clearTimeout(ownerTimer);
    ownerTimer = setTimeout(refresh, 200);
  });
}

function bindAlertDialog() {
  els.newAlert.addEventListener("click", () => els.dialog.showModal());
  els.alertCancel.addEventListener("click", () => els.dialog.close());
  els.alertForm.addEventListener("submit", async (event) => {
    event.preventDefault();
    const data = new FormData(els.alertForm);
    const payload = {
      fingerprint: data.get("fingerprint"),
      title: data.get("title"),
      severity: data.get("severity"),
      source: data.get("source") || "unknown",
    };
    const result = await fetchJson("/api/alerts", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload),
    });
    if (result.ok) {
      setFeedback(result.status === 201 ? "Incident created" : "Alert merged into existing incident", "ok");
      els.alertForm.reset();
      els.dialog.close();
      await refresh();
    } else {
      setFeedback((result.body && result.body.error) || "Could not create alert", "error");
    }
  });
}

function getState() {
  return {
    filters: { ...state.filters },
    selectedIncidentId: state.selectedIncidentId,
    incidents: state.incidents.map((i) => ({ ...i })),
    feedback: state.feedback,
  };
}

window.incidentOps = {
  refresh,
  selectIncident,
  getState,
};

bindFilters();
bindAlertDialog();
refresh();

